 /**
  * Creates instructions required to deposit sol to stake pool.
  */
 export async function depositSol(
   connection: Connection,
   stakePoolAddress: PublicKey,
   from: PublicKey,
   lamports: number,
   destinationTokenAccount?: PublicKey,
   referrerTokenAccount?: PublicKey,
   depositAuthority?: PublicKey,
 ) {
   const fromBalance = await connection.getBalance(from, 'confirmed');
   if (fromBalance < lamports) {
     throw new Error(
       `Not enough SOL to deposit into pool. Maximum deposit amount is ${lamportsToSol(
         fromBalance,
       )} SOL.`,
     );
   }

   const stakePoolAccount = await getStakePoolAccount(connection, stakePoolAddress);
   const stakePool = stakePoolAccount.account.data;

   // Ephemeral SOL account just to do the transfer
   const userSolTransfer = new Keypair();
   const signers: Signer[] = [userSolTransfer];
   const instructions: TransactionInstruction[] = [];

   let rentFee = 0;

   // Create the ephemeral SOL account
   instructions.push(
     SystemProgram.transfer({
       fromPubkey: from,
       toPubkey: userSolTransfer.publicKey,
       lamports,
     }),
   );

   // Create token account if not specified
   if (!destinationTokenAccount) {
     const { associatedAddress, rentFee: fee } = await addAssociatedTokenAccount(
       connection,
       from,
       stakePool.poolMint,
       instructions,
     );
     destinationTokenAccount = associatedAddress;
     rentFee += fee;
   }

   const withdrawAuthority = await findWithdrawAuthorityProgramAddress(
     STAKE_POOL_PROGRAM_ID,
     stakePoolAddress,
   );

   instructions.push(
     StakePoolInstruction.depositSol({
       stakePool: stakePoolAddress,
       reserveStake: stakePool.reserveStake,
       fundingAccount: userSolTransfer.publicKey,
       destinationPoolAccount: destinationTokenAccount,
       managerFeeAccount: stakePool.managerFeeAccount,
       referralPoolAccount: referrerTokenAccount ?? destinationTokenAccount,
       poolMint: stakePool.poolMint,
       lamports,
       withdrawAuthority,
       depositAuthority,
     }),
   );

   return {
     instructions,
     signers,
     rentFee,
   };
 }

