1. import { Connection, PublicKey, TransactionInstruction } from '@solana/web3.js';
2. import {
3.   ASSOCIATED_TOKEN_PROGRAM_ID,
4.   TOKEN_PROGRAM_ID,
5.   Mint,
6.   createAssociatedTokenAccountInstruction,
7.   getAssociatedTokenAddress,
8.   getMint,
9. } from '@solana/spl-token';
10. import { AccountLayout, TokenAccount } from '../layouts';
11. 
12. const FAILED_TO_FIND_ACCOUNT = 'Failed to find account';
13. const INVALID_ACCOUNT_OWNER = 'Invalid account owner';
14. 
15. export async function getTokenMint(
16.   connection: Connection,
17.   tokenMintPubkey: PublicKey,
18. ): Promise<Mint | undefined> {
19.   return getMint(connection, tokenMintPubkey, undefined, TOKEN_PROGRAM_ID);
20. }
21. 
22. /**
23.  * Retrieve the associated account or create one if not found.
24.  * This account may then be used as a `transfer()` or `approve()` destination
25.  */
26. export async function addAssociatedTokenAccount(
27.   connection: Connection,
28.   owner: PublicKey,
29.   mint: PublicKey,
30.   instructions: TransactionInstruction[],
31. ) {
32.   const associatedAddress = await getAssociatedTokenAddress(
33.     mint,
34.     owner,
35.     false,
36.     TOKEN_PROGRAM_ID,
37.     ASSOCIATED_TOKEN_PROGRAM_ID,
38.   );
39. 
40.   let rentFee = 0;
41. 
42.   // This is the optimum logic, considering TX fee, client-side computation,
43.   // RPC roundtrips and guaranteed idempotent.
44.   // Sadly we can't do this atomically;
45.   try {
46.     const account = await connection.getAccountInfo(associatedAddress);
47.     if (!account) {
48.       // noinspection ExceptionCaughtLocallyJS
49.       throw new Error(FAILED_TO_FIND_ACCOUNT);
50.     }
51.   } catch (err: any) {
52.     // INVALID_ACCOUNT_OWNER can be possible if the associatedAddress has
53.     // already been received some lamports (= became system accounts).
54.     // Assuming program derived addressing is safe, this is the only case
55.     // for the INVALID_ACCOUNT_OWNER in this code-path
56.     if (err.message === FAILED_TO_FIND_ACCOUNT || err.message === INVALID_ACCOUNT_OWNER) {
57.       instructions.push(
58.         createAssociatedTokenAccountInstruction(
59.           owner,
60.           associatedAddress,
61.           owner,
